//! 📥️ Original AppFrame bytes are decoded in bounded Source slices into one retained typed recipient.
use std::mem::size_of;
use semio_framework_job::{OriginalSourceBinding,OriginalTurnFailure,StepContext};
use semio_framework_value::{RetainedCloneGrant as Grant,RetainedCloneProgress as Progress,RetainedCloneStep as Step,RetainedWorkOutcome as Turn,RetirementDemand as Demand,ValueError,ValueRefusalKind,retained_clone_grant_admits,retirement::{RetireOwned,controlled::ControlledRetirement}};
use protocol::wire::command_ingress::{OriginalBinaryReadSource,OriginalBinarySlice,OriginalCommandVarint,OriginalCommandField};
use semio_os_channel::{AppFrame,AppDocumentIdentity,ChildPackEntry,ChildHeadPackEntry,WindowConfigPackEntry,DocumentArchivePack,DocumentArchiveArtifactRef,DocumentArchiveOwnerRef,OwnedDocumentMemberPackEntry,DocumentArchiveLoadState,DocumentArchiveLoadStatus,MediaExportHandleWire,MediaExportStateWire};
#[path="🧭️plan/🦀️.rs"]mod plan;
#[path="📦️fields/🦀️.rs"]mod fields;
#[path="📚️lists/🦀️.rs"]mod lists;
#[path="🔗️causal/🦀️.rs"]mod causal;
#[path="🏠️query/🦀️.rs"]mod query;
use fields::Fields;
use plan::Atom;
fn invalid(message:&'static str)->OriginalTurnFailure{ValueError::literal(ValueRefusalKind::InvalidValue,message).into()}
fn pay(cx:&mut StepContext<'_>,copy:usize,work:u64)->Result<bool,OriginalTurnFailure>{if cx.retirement_should_yield()||cx.fuel_remaining()<work||!retained_clone_grant_admits(cx.retained_grant(),Demand{copy_bytes:copy,depth:1,..Default::default()}){return Ok(false)}cx.consume_retained(Progress{copied_items:1,copied_bytes:copy,..Default::default()})?;cx.consume_fuel(work);Ok(true)}
fn debit(turn:Turn<Step>,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{cx.consume_fuel(turn.work);match turn.result{Ok(step)=>cx.consume_retained(step.progress()).map_err(Into::into),Err(error)=>Err(OriginalTurnFailure::debit_original(error,cx))}}
fn receive_native_step(cx:&mut StepContext<'_>,run:impl FnOnce(&mut semio_framework_value_native_owned::NativeDecodeControl<'_>)->Turn<Step,semio_framework_value_native_owned::OriginalReceivingPrimary>)->Result<Step,OriginalTurnFailure>{
 let before=cx.fuel_remaining();let mut produced=None;let context=cx.with_native_receiving::<(),ValueError>(|native|{produced=Some(run(native));Ok(())});let work=produced.as_ref().map_or(0,|turn|turn.work);cx.consume_fuel(work);let progress=produced.as_ref().map_or_else(||cx.receiving_child_progress(),|turn|match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.progress});let settled=match cx.receiving_issued_grant(){Some(issued)=>cx.consume_receiving_retained(issued,progress),None=>if progress==Progress::default(){Ok(())}else{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"AppFrame receiving omitted its actual issued scope").with_retained_progress(progress))}};let context=context.err();let receipt=settled.err();let work_refusal=(work>before).then(||ValueError::literal(ValueRefusalKind::WorkLimit,"AppFrame native child exceeded its actual finite work"));
 match produced{Some(Turn{result:Err(primary),..})=>{let mut failure=OriginalTurnFailure::from(primary);failure.context_refusal=context;failure.receipt_refusal=receipt;failure.work_refusal=work_refusal;Err(failure)},Some(Turn{result:Ok(step),..})=>{if context.is_none()&&receipt.is_none()&&work_refusal.is_none(){return Ok(step)}let mut failure=OriginalTurnFailure::from(ValueError::literal(ValueRefusalKind::InvariantViolated,"AppFrame original native receipt was refused").with_retained_progress(progress));failure.context_refusal=context;failure.receipt_refusal=receipt;failure.work_refusal=work_refusal;Err(failure)},None=>{let mut failure=OriginalTurnFailure::from(context.unwrap_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"AppFrame native operation was not submitted")));failure.receipt_refusal=receipt;failure.work_refusal=work_refusal;Err(failure)}}
}
/// 📏️ The embedding supplies explicit finite data limits; these are never work authority.
#[derive(Clone,Copy)]
pub struct NativeAppFrameLimits{pub maximum_bytes:usize,pub maximum_field_bytes:usize,pub maximum_entries:usize}
#[derive(Default,semio_framework_value::RetireOwned)]
#[value(crate="::semio_framework_value")]
struct Partial{tag:Option<u8>,index:usize,offset:usize,varint:OriginalCommandVarint,field:OriginalCommandField,data:Fields,list:lists::List,query:query::Query,frame:Option<AppFrame>,handle_stage:u8,identity_stage:u8}
/// 🧳️ The producer payload is borrowed afresh; partial fields and the complete result remain Source-owned.
pub struct NativeAppFrameReceiver{limits:NativeAppFrameLimits,binding:Option<OriginalSourceBinding>,source:Option<(usize,usize)>,partial:Option<Partial>,close:Option<ControlledRetirement<Partial>>,delivered:bool}
impl NativeAppFrameReceiver{
 pub fn new(limits:NativeAppFrameLimits)->Result<Self,ValueError>{if limits.maximum_bytes==0||limits.maximum_field_bytes==0||limits.maximum_field_bytes>limits.maximum_bytes||limits.maximum_entries==0{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"AppFrame decoding requires explicit nonzero finite limits"))}Ok(Self{limits,binding:None,source:None,partial:Some(Partial::default()),close:None,delivered:false})}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{cx.original_source_parent()?.validate_borrowed_context(cx)?;if self.binding.is_some_and(|binding|!binding.matches(cx)){return Err(invalid("AppFrame receiver changed its actual Source"))}Ok(())}
 pub fn advance_from(&mut self,source:&[u8],cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;if self.close.is_some()||self.delivered||self.partial.is_none(){return Err(invalid("AppFrame receiving cannot resume after delivery or retirement"))}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"AppFrame receiving cancelled").into())}if cx.should_yield(){return Ok(false)}
  if source.len()>self.limits.maximum_bytes{return Err(invalid("AppFrame payload exceeds its declared byte limit"))}let identity=(source.as_ptr()as usize,source.len());if self.source.is_some_and(|old|old!=identity){return Err(invalid("AppFrame receiving changed its actual immutable payload"))}
  if self.source.is_none(){if pay(cx,size_of::<Option<OriginalSourceBinding>>()+size_of::<Option<(usize,usize)>>(),1)?{self.binding=Some(OriginalSourceBinding::borrow(cx));self.source=Some(identity)}return Ok(false)}
  let partial=self.partial.as_mut().unwrap();if partial.frame.is_some(){return Ok(true)}
  if partial.tag.is_none(){let turn=OriginalBinarySlice::new(source,&mut partial.offset)?.read_byte_source_step(&mut partial.tag,cx.retained_grant(),cx.fuel_remaining());debit(turn,cx)?;return Ok(false)}
  let ready=match plan::plan(partial.tag.unwrap(),partial.index)?{
   Atom::Number(i)=>partial.number(source,i,cx)?,Atom::Byte(i)=>partial.byte(source,i,cx)?,Atom::Optional(i,flag)=>partial.optional(source,i,flag,cx)?,Atom::Bytes(i)=>partial.field(source,i,false,self.limits.maximum_field_bytes,cx)?,Atom::Text(i)=>partial.field(source,i,true,self.limits.maximum_field_bytes,cx)?,
   Atom::Handle=>partial.handle(source,self.limits.maximum_field_bytes,cx)?,Atom::Identity=>partial.identity(source,cx)?,Atom::List(kind)=>partial.list.advance(source,&mut partial.offset,&mut partial.data,kind,self.limits,cx)?,Atom::Archive=>partial.list.archive(source,&mut partial.offset,&mut partial.data.archive,self.limits,cx)?,Atom::Query=>partial.query.advance(source,&mut partial.offset,&mut partial.data.query,cx)?,
   Atom::Finish=>{if partial.offset!=source.len(){return Err(invalid("AppFrame carries trailing bytes after its exact binary fields"))}let bytes=size_of::<Fields>()+size_of::<Option<AppFrame>>();if pay(cx,bytes,1)?{partial.frame=Some(partial.data.build(partial.tag.unwrap()))}return Ok(partial.frame.is_some())}
  };if ready&&pay(cx,size_of::<usize>(),1)?{partial.index+=1}Ok(false)
 }
 pub fn with_frame_step(&self,cx:&mut StepContext<'_>,receive:impl FnOnce(&AppFrame,&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;let Some(frame)=self.partial.as_ref().and_then(|p|p.frame.as_ref())else{return Ok(false)};if !pay(cx,size_of::<&AppFrame>(),1)?{return Ok(false)}receive(frame,cx)?;Ok(true)}
 pub fn take_into_step(&mut self,output:&mut Option<AppFrame>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if output.is_some(){return Err(invalid("AppFrame original destination is occupied"))}let Some(partial)=self.partial.as_mut()else{return Ok(false)};if partial.frame.is_none(){return Ok(false)}if !pay(cx,2*size_of::<Option<AppFrame>>()+size_of::<bool>(),1)?{return Ok(false)}*output=partial.frame.take();self.delivered=true;Ok(true)}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.partial.is_some(){if !pay(cx,size_of::<Option<Partial>>()+size_of::<Option<ControlledRetirement<Partial>>>(),1)?{return Ok(false)}self.close=Some(ControlledRetirement::retain(self.partial.take().unwrap()));return Ok(false)}if let Some(owner)=self.close.as_mut(){if owner.terminal_is_empty(){if !pay(cx,size_of::<Option<ControlledRetirement<Partial>>>(),1)?{return Ok(false)}self.close.take();return Ok(true)}let body=cx.retained_grant().maximum_copy_bytes;let demand=owner.next_demand(body)?;let work=owner.next_computational_work(body)?;if cx.fuel_remaining()<work||!retained_clone_grant_admits(cx.retained_grant(),demand){return Ok(false)}let result=owner.step(cx.retained_grant());cx.consume_fuel(owner.last_turn_work());match result{Ok(step)=>cx.consume_retained(step.progress())?,Err(error)=>return Err(OriginalTurnFailure::debit_original(error,cx))}return Ok(false)}Ok(true)}
 pub fn terminal_is_empty(&self)->bool{self.partial.is_none()&&self.close.is_none()}
}
impl Partial{
 fn number(&mut self,source:&[u8],index:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.data.numbers[index].is_some(){return Ok(true)}let turn=if self.varint.value().is_some(){self.varint.transfer_source_step(&mut self.data.numbers[index],cx.retained_grant(),cx.fuel_remaining())}else{self.varint.step(&mut OriginalBinarySlice::new(source,&mut self.offset)?,cx.retained_grant(),cx.fuel_remaining())};debit(turn,cx)?;if self.data.numbers[index].is_some_and(|n|(matches!(self.tag,Some(28|29|30|31))&&index==1)&&n>u32::MAX as u64){return Err(invalid("AppFrame instance exceeds u32"))}Ok(false)}
 fn byte(&mut self,source:&[u8],index:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if let Some(value)=self.data.flags[index]{let maximum=if self.tag==Some(27)&&index==0{4}else if self.tag==Some(29)&&index==0{3}else{1};if value>maximum{return Err(invalid("AppFrame discriminator exceeds its authored range"))}return Ok(true)}debit(OriginalBinarySlice::new(source,&mut self.offset)?.read_byte_source_step(&mut self.data.flags[index],cx.retained_grant(),cx.fuel_remaining()),cx)?;Ok(false)}
 fn optional(&mut self,source:&[u8],index:usize,flag:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.byte(source,flag,cx)?{return Ok(false)}if self.data.flags[flag]==Some(0){return Ok(true)}self.number(source,index,cx)}
 fn field(&mut self,source:&[u8],index:usize,text:bool,maximum:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if if text{self.data.texts[index].is_some()}else{self.data.bytes[index].is_some()}{return Ok(true)}let turn=if self.field.bytes().is_some(){if text{if self.tag==Some(31)&&index==0&&self.field.characters().is_none_or(|n|n==0||n>512){return Err(invalid("AppFrame document identity has an invalid character extent"))}self.field.transfer_text_source_step(&mut self.data.texts[index],cx.retained_grant(),cx.fuel_remaining())}else{self.field.transfer_bytes_source_step(&mut self.data.bytes[index],cx.retained_grant(),cx.fuel_remaining())}}else{self.field.step(&mut OriginalBinarySlice::new(source,&mut self.offset)?,maximum,text,cx.retained_grant(),cx.fuel_remaining())};debit(turn,cx)?;Ok(false)}
 fn handle(&mut self,source:&[u8],maximum:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.handle_stage==5{return Ok(true)}let ready=match self.handle_stage{0=>self.number(source,1,cx)?,1=>self.field(source,0,true,maximum,cx)?,2..=4=>self.number(source,self.handle_stage as usize,cx)?,_=>unreachable!()};if ready&&pay(cx,size_of::<u8>(),1)?{self.handle_stage+=1}Ok(false)}
 fn identity(&mut self,source:&[u8],cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.byte(source,0,cx)?{return Ok(false)}if self.data.flags[0]==Some(0){return Ok(true)}self.field(source,0,true,2048,cx)}
}

impl semio_framework_job::OriginalNativeRetirement for NativeAppFrameReceiver{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.close_step(cx)}fn terminal_is_empty(&self)->bool{Self::terminal_is_empty(self)}}
impl Drop for NativeAppFrameReceiver{fn drop(&mut self){assert!(std::thread::panicking()||self.source.is_none()||self.terminal_is_empty(),"original AppFrame receiver requires funded physical retirement")}}
